--
-- Name: close_expired_jardins(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_expired_jardins() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  closed_count INTEGER;
BEGIN
  UPDATE public.jardim_heroina
  SET 
    status = 'closed',
    fechado_em = now(),
    updated_at = now()
  WHERE 
    status = 'active'
    AND gesto_prazo IS NOT NULL
    AND gesto_prazo < CURRENT_DATE;
  
  GET DIAGNOSTICS closed_count = ROW_COUNT;
  RETURN closed_count;
END;
$$;


