--
-- Name: co_validate_detector_evento(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.co_validate_detector_evento() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.detector_tipo NOT IN ('estagnacao','dissociacao','evitacao','fusao') THEN
    RAISE EXCEPTION 'detector_tipo inválido: %', NEW.detector_tipo;
  END IF;
  IF NEW.intensidade NOT IN ('baixa','media','alta') THEN
    RAISE EXCEPTION 'intensidade inválida: %', NEW.intensidade;
  END IF;
  IF NEW.origem NOT IN ('heuristica','ia','hibrido','jardim','sessao') THEN
    RAISE EXCEPTION 'origem inválida: %', NEW.origem;
  END IF;
  IF NEW.contexto IS NOT NULL AND NEW.contexto NOT IN ('jardim','sessao') THEN
    RAISE EXCEPTION 'contexto inválido: %', NEW.contexto;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: co_validate_intervencao_aplicada(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.co_validate_intervencao_aplicada() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.tipo_intervencao NOT IN (
    'pergunta_ruptura','confronto_leve','grounding_corpo',
    'separacao_simbolica','sustentar_presenca'
  ) THEN
    RAISE EXCEPTION 'tipo_intervencao inválido: %', NEW.tipo_intervencao;
  END IF;
  IF NEW.categoria_alvo IS NOT NULL AND NEW.categoria_alvo NOT IN (
    'estagnacao','evitacao','dissociacao','fusao'
  ) THEN
    RAISE EXCEPTION 'categoria_alvo inválida: %', NEW.categoria_alvo;
  END IF;
  IF NEW.percepcao_terapeuta IS NOT NULL AND NEW.percepcao_terapeuta NOT IN (
    'eficaz','neutra','sem_efeito'
  ) THEN
    RAISE EXCEPTION 'percepcao_terapeuta inválida: %', NEW.percepcao_terapeuta;
  END IF;
  RETURN NEW;
END;
$$;


