        SELECT 1 FROM public.confirmacao_profissional
        WHERE user_id = _user_id
        AND aceita_codigo_etico = true
    )
$$;


--
-- Name: log_automation_simulation(text, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_automation_simulation(p_risk_type text, p_action_type text, p_channel text, p_portal text, p_admin_id uuid, p_snapshot jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_audit_id UUID;
BEGIN
    INSERT INTO public.admin_automation_audit (action, reason, snapshot_data, admin_id)
    VALUES ('simulate', 'Simulação de impacto para ' || p_risk_type || ' / ' || p_action_type, p_snapshot, p_admin_id)
    RETURNING id INTO v_audit_id;
    RETURN v_audit_id;
END;
$$;


--
-- Name: move_to_dlq(text, text, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.move_to_dlq(source_queue text, dlq_name text, message_id bigint, payload jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE new_id BIGINT;
BEGIN
  SELECT pgmq.send(dlq_name, payload) INTO new_id;
  PERFORM pgmq.delete(source_queue, message_id);
  RETURN new_id;
EXCEPTION WHEN undefined_table THEN
  BEGIN
    PERFORM pgmq.create(dlq_name);
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  SELECT pgmq.send(dlq_name, payload) INTO new_id;
  BEGIN
    PERFORM pgmq.delete(source_queue, message_id);
  EXCEPTION WHEN undefined_table THEN
    NULL;
  END;
  RETURN new_id;
END;
$$;


--
-- Name: notify_admin_degustacao_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_admin_degustacao_request() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  admin_ids UUID[];
  admin_id UUID;
  user_name TEXT;
BEGIN
  -- Get all admin IDs from user_roles table
  SELECT ARRAY_AGG(user_id) INTO admin_ids
  FROM public.user_roles
  WHERE portal = 'admin';
  
  -- Get user name using correct field 'nome'
  SELECT COALESCE(nome, email, 'Visitante') INTO user_name
  FROM public.profiles
  WHERE id = NEW.user_id;
  
  -- Create notification for each admin using correct table 'notifications'
  IF admin_ids IS NOT NULL THEN
    FOREACH admin_id IN ARRAY admin_ids
    LOOP
      INSERT INTO public.notifications (user_id, type, title, body)
      VALUES (
        admin_id,
        'info',
        'Novo pedido de degustação',
        user_name || ' solicitou acesso de degustação por 24h.'
      );
    END LOOP;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: oraculo_portal_pode_publicar(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.oraculo_portal_pode_publicar(p_portal_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT
    EXISTS (SELECT 1 FROM public.oraculo_portal_essencia e WHERE e.portal_id = p_portal_id)
    AND EXISTS (SELECT 1 FROM public.oraculo_portal_audios a WHERE a.portal_id = p_portal_id AND a.tipo = 'principal')
    AND EXISTS (SELECT 1 FROM public.oraculo_portal_laboratorios l WHERE l.portal_id = p_portal_id)
    AND EXISTS (SELECT 1 FROM public.oraculo_portal_jardins j WHERE j.portal_id = p_portal_id)
    AND EXISTS (SELECT 1 FROM public.oraculo_portal_aplicacoes ap WHERE ap.portal_id = p_portal_id)
    AND EXISTS (SELECT 1 FROM public.oraculo_portal_narroterapia n WHERE n.portal_id = p_portal_id)
    AND EXISTS (SELECT 1 FROM public.oraculo_portal_forjas f WHERE f.portal_id = p_portal_id)
    AND EXISTS (SELECT 1 FROM public.oraculo_portal_ferramentas ft WHERE ft.portal_id = p_portal_id)
    AND EXISTS (SELECT 1 FROM public.oraculo_portal_riscos_eticos r WHERE r.portal_id = p_portal_id);
$$;


--
-- Name: process_webhook_subscription(uuid, text, text, text, text, text, timestamp with time zone, timestamp with time zone, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_webhook_subscription(_user_id uuid, _provider text, _plan_id text, _status text, _portal text, _subscription_status_profile text, _current_period_start timestamp with time zone, _current_period_end timestamp with time zone, _next_billing_date timestamp with time zone, _external_subscription_id text, _customer_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _sub_id uuid;
  _result jsonb;
BEGIN
  -- Step 1: Upsert subscription (SOURCE OF TRUTH)
  INSERT INTO subscriptions (user_id, provider, plan_id, status, current_period_start, current_period_end, next_billing_date, external_subscription_id, last_event_at)
  VALUES (_user_id, _provider, _plan_id, _status, _current_period_start, _current_period_end, _next_billing_date, _external_subscription_id, now())
  ON CONFLICT (user_id, provider) DO UPDATE SET
    plan_id = EXCLUDED.plan_id,
    status = EXCLUDED.status,
    current_period_start = COALESCE(EXCLUDED.current_period_start, subscriptions.current_period_start),
    current_period_end = COALESCE(EXCLUDED.current_period_end, subscriptions.current_period_end),
    next_billing_date = EXCLUDED.next_billing_date,
    external_subscription_id = COALESCE(EXCLUDED.external_subscription_id, subscriptions.external_subscription_id),
    last_event_at = now(),
    updated_at = now()
  RETURNING id INTO _sub_id;

  -- Step 2: Sync profiles (DERIVED from subscription)
  UPDATE profiles SET
    portal = _portal::portal_type,
    subscription_status = _subscription_status_profile,
    access_expires_at = CASE WHEN _status = 'active' THEN NULL ELSE access_expires_at END,
    nome = COALESCE(_customer_name, nome),
    updated_at = now()
  WHERE id = _user_id;

  -- Step 3: Sync user_roles (DERIVED from subscription)
  UPDATE user_roles SET portal = _portal::portal_type
  WHERE user_id = _user_id;

  _result := jsonb_build_object(
    'subscription_id', _sub_id,
    'user_id', _user_id,
    'portal', _portal,
    'status', _status
  );

  RETURN _result;
END;
$$;


--
-- Name: protect_narroterapia_suspension_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_narroterapia_suspension_fields() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Se não for admin e tentar alterar campos de suspensão, reverte
  IF NOT public.is_admin(auth.uid()) THEN
    NEW.suspenso := OLD.suspenso;
    NEW.suspenso_em := OLD.suspenso_em;
    NEW.suspenso_por := OLD.suspenso_por;
    NEW.motivo_suspensao := OLD.motivo_suspensao;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: protect_profile_privileged_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_profile_privileged_fields() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_admin(auth.uid()) THEN
    NEW.role := OLD.role;
    NEW.portal := OLD.portal;
    NEW.access_status := OLD.access_status;
    NEW.subscription_status := OLD.subscription_status;
    NEW.access_expires_at := OLD.access_expires_at;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: read_email_batch(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_email_batch(queue_name text, batch_size integer, vt integer) RETURNS TABLE(msg_id bigint, read_ct integer, message jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY SELECT r.msg_id, r.read_ct, r.message FROM pgmq.read(queue_name, vt, batch_size) r;
EXCEPTION WHEN undefined_table THEN
  PERFORM pgmq.create(queue_name);
  RETURN;
END;
$$;


--
-- Name: refresh_founder_daily_metrics(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_founder_daily_metrics(target_date date) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_new_sales_val BIGINT;
    v_new_sales_count INTEGER;
    v_renewals_val BIGINT;
    v_renewals_count INTEGER;
    v_refunds_val BIGINT;
    v_refunds_count INTEGER;
    v_mrr BIGINT;
    v_stripe_costs BIGINT;
    v_ia_costs BIGINT;
BEGIN
    -- 1. Aggregating Revenue from payments (assuming a payments table exists or similar structure)
    -- This is a placeholder logic that should be adjusted to the actual schema
    SELECT 
        COALESCE(SUM(amount), 0), COUNT(*)
    INTO v_new_sales_val, v_new_sales_count
    FROM public.payments -- Adjust to actual table name
    WHERE date_trunc('day', created_at)::date = target_date 
    AND status = 'succeeded' 
    AND metadata->>'type' = 'new_sale';

    -- 2. Aggregating IA Costs (assuming logs exist)
    -- Placeholder: 1 token = 0.00001 cents or similar
    SELECT COALESCE(SUM(total_tokens), 0) * 0.01 -- Adjust factor
    INTO v_ia_costs
    FROM public.ai_interaction_logs
    WHERE date_trunc('day', created_at)::date = target_date;

    -- 3. Upsert into daily table
    INSERT INTO public.founder_financial_daily (
        date, 
        new_sales_count, 
        new_sales_value, 
        cost_ia,
        updated_at
    )
    VALUES (
        target_date, 
        v_new_sales_count, 
        v_new_sales_val, 
        v_ia_costs,
        now()
    )
    ON CONFLICT (date) DO UPDATE SET
        new_sales_count = EXCLUDED.new_sales_count,
        new_sales_value = EXCLUDED.new_sales_value,
        cost_ia = EXCLUDED.cost_ia,
        updated_at = now();
END;
$$;


--
-- Name: refresh_student_progress(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_student_progress(_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _total_events INT;
  _last_access TIMESTAMPTZ;
  _lessons INT;
  _practices_s INT;
  _practices_c INT;
  _questions INT;
  _reflections INT;
  _training INT;
  _engagement TEXT;
  _consistency TEXT;
  _days_since_last INT;
  _active_days_30 INT;
  _pattern TEXT;
  _signal TEXT;
  _next_step TEXT;
  _ready BOOLEAN;
  _bottleneck TEXT;
BEGIN
  -- Count metrics from events
  SELECT COUNT(*) INTO _total_events
  FROM student_learning_events WHERE user_id = _user_id;

  SELECT MAX(created_at) INTO _last_access
  FROM student_learning_events WHERE user_id = _user_id;

  SELECT COUNT(*) INTO _lessons
  FROM student_learning_events
  WHERE user_id = _user_id AND action_type = 'completed' AND object_type IN ('aula', 'modulo');

  SELECT COUNT(*) INTO _practices_s
  FROM student_learning_events
  WHERE user_id = _user_id AND action_type = 'started_practice';

  SELECT COUNT(*) INTO _practices_c
  FROM student_learning_events
  WHERE user_id = _user_id AND action_type = 'finished_practice';

  SELECT COUNT(*) INTO _questions
  FROM student_learning_events
  WHERE user_id = _user_id AND action_type = 'asked_question';

  SELECT COUNT(*) INTO _reflections
  FROM student_learning_events
  WHERE user_id = _user_id AND action_type = 'saved_reflection';

  SELECT COUNT(*) INTO _training
  FROM student_learning_events
  WHERE user_id = _user_id AND context_area = 'treinamento' AND action_type = 'completed';

  -- Engagement level
  _days_since_last := EXTRACT(DAY FROM now() - COALESCE(_last_access, now() - interval '999 days'));

  SELECT COUNT(DISTINCT DATE(created_at)) INTO _active_days_30
  FROM student_learning_events
  WHERE user_id = _user_id AND created_at > now() - interval '30 days';

  IF _active_days_30 >= 12 THEN _engagement := 'alto';
  ELSIF _active_days_30 >= 4 THEN _engagement := 'medio';
  ELSE _engagement := 'baixo';
  END IF;

  -- Consistency pattern
  IF _active_days_30 >= 12 THEN _consistency := 'consistente';
  ELSIF _active_days_30 >= 4 THEN _consistency := 'ocasional';
  ELSE _consistency := 'interrompido';
  END IF;

  -- Learning pattern and pedagogical signal
  IF _practices_c > 0 AND _practices_c >= _practices_s * 0.7 AND _lessons > 0 THEN
    _pattern := 'praticante_ativa';
    _signal := 'engajamento consistente';
    _ready := true;
  ELSIF _questions > _practices_c * 3 AND _practices_c < 2 THEN
    _pattern := 'conceitual_sem_pratica';
    _signal := 'precisa de mais aplicação prática';
    _ready := false;
  ELSIF _lessons > 3 AND _practices_s = 0 THEN
    _pattern := 'consumidora_passiva';
    _signal := 'consome conteúdo sem praticar';
    _ready := false;
  ELSIF _days_since_last > 14 THEN
    _pattern := 'ausente';
    _signal := 'risco de abandono';
    _ready := false;
  ELSIF _days_since_last > 7 AND _engagement = 'baixo' THEN
    _pattern := 'estagnou';
    _signal := 'estagnação na estação atual';
    _ready := false;
  ELSE
    _pattern := 'em_progresso';
    _signal := 'em desenvolvimento';
    _ready := false;
  END IF;

  -- Bottleneck
  IF _practices_s > 0 AND _practices_c = 0 THEN
    _bottleneck := 'praticas_incompletas';
  ELSIF _lessons = 0 AND _total_events > 5 THEN
    _bottleneck := 'sem_conclusao_aulas';
  ELSE
    _bottleneck := NULL;
  END IF;

  -- Next step
  IF _ready THEN
    _next_step := 'pronta para avançar';
  ELSIF _pattern = 'conceitual_sem_pratica' THEN
    _next_step := 'iniciar prática guiada';
  ELSIF _pattern = 'consumidora_passiva' THEN
    _next_step := 'experimentar ferramenta simbólica';
  ELSIF _pattern = 'ausente' THEN
    _next_step := 'reengajar com conteúdo leve';
  ELSE
    _next_step := 'continuar trilha atual';
  END IF;

  -- Upsert progress
  INSERT INTO student_learning_progress (
    user_id, lessons_completed, practices_started, practices_completed,
    questions_to_ai_count, reflections_count, training_cases_completed,
    last_access_at, engagement_level, consistency_pattern,
    current_bottleneck, learning_pattern, pedagogical_signal,
    suggested_next_step, ready_for_next_step, updated_at
  ) VALUES (
    _user_id, _lessons, _practices_s, _practices_c,
    _questions, _reflections, _training,
    _last_access, _engagement, _consistency,
    _bottleneck, _pattern, _signal,
    _next_step, _ready, now()
  )
  ON CONFLICT (user_id) DO UPDATE SET
    lessons_completed = EXCLUDED.lessons_completed,
    practices_started = EXCLUDED.practices_started,
    practices_completed = EXCLUDED.practices_completed,
    questions_to_ai_count = EXCLUDED.questions_to_ai_count,
    reflections_count = EXCLUDED.reflections_count,
    training_cases_completed = EXCLUDED.training_cases_completed,
    last_access_at = EXCLUDED.last_access_at,
    engagement_level = EXCLUDED.engagement_level,
    consistency_pattern = EXCLUDED.consistency_pattern,
    current_bottleneck = EXCLUDED.current_bottleneck,
    learning_pattern = EXCLUDED.learning_pattern,
    pedagogical_signal = EXCLUDED.pedagogical_signal,
    suggested_next_step = EXCLUDED.suggested_next_step,
    ready_for_next_step = EXCLUDED.ready_for_next_step,
    updated_at = now();
END;
$$;


--
-- Name: refresh_upsell_opportunities(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_upsell_opportunities() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
    rule RECORD;
    prob_score DOUBLE PRECISION;
    hist_rate DOUBLE PRECISION;
    t_factor DOUBLE PRECISION;
BEGIN
    FOR rule IN SELECT * FROM public.upsell_rules WHERE is_active = true LOOP
        -- Calculate some mock "historical rates" based on rule priority
        hist_rate := CASE 
            WHEN rule.segment_from = 'Clube' THEN 0.25 
            WHEN rule.segment_from = 'Formação' THEN 0.18
            ELSE 0.12
        END;

        -- Timing factor based on weekday/time (mock logic)
        t_factor := 0.9 + (random() * 0.2); 

        INSERT INTO public.upsell_opportunities (
            user_id, 
            rule_id, 
            segment_from, 
            segment_to, 
            reason, 
            engagement_score, 
            churn_risk, 
            status,
            historical_segment_rate,
            timing_factor,
            probability_score,
            probability_reason,
            estimated_value,
            touch_count
        )
        SELECT 
            p.id, 
            rule.id, 
            rule.segment_from, 
            rule.segment_to,
            'Comportamento detectado elegível para upgrade ' || rule.segment_to,
            0.7 + (random() * 0.25), -- Mock engagement
            0.05 + (random() * 0.1), -- Mock low churn
            'pending',
            hist_rate,
            t_factor,
            ((0.7 + (random() * 0.25)) * hist_rate * t_factor), -- probability_score
            'Alta recorrência no portal ' || rule.segment_from || ' com score de engajamento consistente.',
            rule.estimated_value_increase,
            0
        FROM public.profiles p
        WHERE 
            -- Rule 1: No active or recently sent opportunities (fatigue)
            NOT EXISTS (
                SELECT 1 FROM public.upsell_opportunities o 
                WHERE o.user_id = p.id 
                AND (
                    o.status IN ('pending', 'sent')
                    OR (o.status = 'ignored' AND o.created_at > now() - interval '30 days')
                    OR (o.paused_until IS NOT NULL AND o.paused_until > now())
                )
            )
            -- Rule 2: User must not have multiple simultaneous offers (as per simplified fatigue request)
            AND NOT EXISTS (
                SELECT 1 FROM public.upsell_opportunities o
                WHERE o.user_id = p.id AND o.status = 'pending'
            )
        LIMIT 3; -- Conservative generation
    END LOOP;
END;
$$;


