--
-- Name: update_cidadela_from_session(uuid, uuid, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_cidadela_from_session(_client_id uuid, _therapist_id uuid, _distrito text DEFAULT NULL::text, _torre text DEFAULT NULL::text, _porta text DEFAULT NULL::text, _arquetipo text DEFAULT NULL::text, _labirinto text DEFAULT NULL::text, _ferramenta text DEFAULT NULL::text, _insight text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.client_cidadela_map (client_id, therapist_id, distrito_atual, ultima_sessao)
  VALUES (_client_id, _therapist_id, _distrito, now())
  ON CONFLICT (client_id, therapist_id) DO UPDATE SET
    distrito_atual = COALESCE(_distrito, client_cidadela_map.distrito_atual),
    torres_identificadas = CASE 
      WHEN _torre IS NOT NULL AND NOT (_torre = ANY(client_cidadela_map.torres_identificadas))
      THEN array_append(client_cidadela_map.torres_identificadas, _torre)
      ELSE client_cidadela_map.torres_identificadas
    END,
    portas_cruzadas = CASE 
      WHEN _porta IS NOT NULL AND NOT (_porta = ANY(client_cidadela_map.portas_cruzadas))
      THEN array_append(client_cidadela_map.portas_cruzadas, _porta)
      ELSE client_cidadela_map.portas_cruzadas
    END,
    arquetipos_emergentes = CASE 
      WHEN _arquetipo IS NOT NULL AND NOT (_arquetipo = ANY(client_cidadela_map.arquetipos_emergentes))
      THEN array_append(client_cidadela_map.arquetipos_emergentes, _arquetipo)
      ELSE client_cidadela_map.arquetipos_emergentes
    END,
    labirintos_visitados = CASE 
      WHEN _labirinto IS NOT NULL AND NOT (_labirinto = ANY(client_cidadela_map.labirintos_visitados))
      THEN array_append(client_cidadela_map.labirintos_visitados, _labirinto)
      ELSE client_cidadela_map.labirintos_visitados
    END,
    ferramentas_utilizadas = CASE 
      WHEN _ferramenta IS NOT NULL AND NOT (_ferramenta = ANY(client_cidadela_map.ferramentas_utilizadas))
      THEN array_append(client_cidadela_map.ferramentas_utilizadas, _ferramenta)
      ELSE client_cidadela_map.ferramentas_utilizadas
    END,
    insights_ia = CASE 
      WHEN _insight IS NOT NULL 
      THEN client_cidadela_map.insights_ia || jsonb_build_object('text', _insight, 'at', now()::text)
      ELSE client_cidadela_map.insights_ia
    END,
    ultima_sessao = now();
END;
$$;


--
-- Name: update_cidadela_on_tool_usage(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_cidadela_on_tool_usage(_session_id uuid, _tool_id uuid, _arquetipo_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _client_id UUID;
  _district_id UUID;
  _district_nome TEXT;
  _proximo_passo_id UUID;
  _proximo_passo_nome TEXT;
  _result JSONB;
BEGIN
  -- 1. Identificar client_id pela sessão
  SELECT client_id INTO _client_id FROM sessions WHERE id = _session_id;
  IF _client_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Sessão não encontrada');
  END IF;

  -- 2. Buscar distrito principal da ferramenta
  SELECT td.district_id, d.nome
  INTO _district_id, _district_nome
  FROM tool_districts td
  JOIN city_districts d ON d.id = td.district_id
  WHERE td.tool_id = _tool_id AND td.tipo = 'principal'
  LIMIT 1;

  -- 3. Upsert client_city_state
  INSERT INTO client_city_state (client_id, distrito_ativo, distrito_id, ultima_ferramenta_id, ultima_sessao_id, arquetipo_ativo)
  VALUES (_client_id, _district_nome, _district_id, _tool_id, _session_id, _arquetipo_id)
  ON CONFLICT (client_id) DO UPDATE SET
    distrito_ativo = COALESCE(_district_nome, client_city_state.distrito_ativo),
    distrito_id = COALESCE(_district_id, client_city_state.distrito_id),
    ultima_ferramenta_id = _tool_id,
    ultima_sessao_id = _session_id,
    arquetipo_ativo = COALESCE(_arquetipo_id, client_city_state.arquetipo_ativo),
    updated_at = now();

  -- 4. Registrar evento em co_city_history
  INSERT INTO co_city_history (client_id, session_id, tool_id, evento, distrito, detalhe)
  VALUES (_client_id, _session_id, _tool_id, 'ferramenta_utilizada', _district_nome,
    'Ferramenta aplicada na sessão');

  -- 5. Atualizar arquétipo se fornecido
  IF _arquetipo_id IS NOT NULL THEN
    UPDATE client_archetype_state
    SET arquitipo_regente_id = _arquetipo_id, updated_at = now()
    WHERE client_id = _client_id;
  END IF;

  -- 6. Buscar próximo passo
  SELECT t2.id, t2.nome
  INTO _proximo_passo_id, _proximo_passo_nome
  FROM tools t
  JOIN tools t2 ON t2.id = t.proximo_passo_id
  WHERE t.id = _tool_id AND t.proximo_passo_id IS NOT NULL;

  -- 7. Criar sugestão se houver próximo passo
  IF _proximo_passo_id IS NOT NULL THEN
    INSERT INTO ai_recommendations (client_id, session_id, tipo, titulo, descricao, tool_sugerida_id, distrito_sugerido_id)
    SELECT _client_id, _session_id, 'proximo_passo',
      'Próximo passo sugerido: ' || _proximo_passo_nome,
      'Baseado no fluxo metodológico após uso da ferramenta',
      _proximo_passo_id,
      td2.district_id
    FROM tool_districts td2
    WHERE td2.tool_id = _proximo_passo_id AND td2.tipo = 'principal'
    LIMIT 1;
  END IF;

  _result := jsonb_build_object(
    'client_id', _client_id,
    'distrito', _district_nome,
    'proximo_passo', _proximo_passo_nome,
    'arquetipo_atualizado', _arquetipo_id IS NOT NULL
  );

  RETURN _result;
END;
$$;


