CREATE FUNCTION public.upsert_pattern_stat(_client_id uuid, _pattern_type public.pattern_stat_type, _pattern_name text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.client_pattern_stats (client_id, pattern_type, pattern_name, occurrence_count, last_seen_at)
  VALUES (_client_id, _pattern_type, _pattern_name, 1, now())
  ON CONFLICT (client_id, pattern_type, pattern_name)
  DO UPDATE SET
    occurrence_count = client_pattern_stats.occurrence_count + 1,
    last_seen_at = now();
END;
$$;


--
-- Name: user_has_portal_access(public.portal_type); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_has_portal_access(required_portal public.portal_type) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  user_portal public.portal_type;
  portal_levels JSONB := '{"visitante": 1, "mentorada": 2, "aluna_formacao": 3, "assinante": 4, "oracula": 5, "admin": 6, "pre_iniciada": 2, "iniciada": 5}'::jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN (portal_levels->>required_portal::text)::int <= 1;
  END IF;
  
  SELECT portal INTO user_portal
  FROM public.user_roles
  WHERE user_id = auth.uid();
  
  IF user_portal IS NULL THEN
    user_portal := 'visitante';
  END IF;
  
  RETURN (portal_levels->>user_portal::text)::int >= (portal_levels->>required_portal::text)::int;
END;
$$;


