-- Name: COLUMN labirinto_portas.campo_pede; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.labirinto_portas.campo_pede IS 'O que este campo pede (ex: sustentação, tempo, presença)';


--
