CREATE TABLE public.radiestesia_graficos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    nome text NOT NULL,
    autor text,
    origem text DEFAULT 'tradicional'::text,
    categoria text DEFAULT 'clinico'::text,
    tipo_leitura text DEFAULT 'campo'::text,
    para_que_serve text,
    quando_nao_usar text,
    observacoes_simbolicas text,
    imagem_url text,
    combinacoes text[] DEFAULT '{}'::text[],
    ordem integer DEFAULT 0,
    ativo boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    link_loja text,
    imagem_fisica_url text,
    disponivel_loja boolean DEFAULT false,
    tipo_acao text,
    quando_usar text,
    como_usar text,
    erro_iniciante text,
    nivel_intensidade text,
    observacao_etica text,
    slug text,
    CONSTRAINT radiestesia_graficos_nivel_intensidade_check CHECK ((nivel_intensidade = ANY (ARRAY['suave'::text, 'medio'::text, 'forte'::text, 'muito_forte'::text])))
);


--
-- Name: COLUMN radiestesia_graficos.link_loja; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.radiestesia_graficos.link_loja IS 'URL específica do produto na loja física';


--
-- Name: COLUMN radiestesia_graficos.imagem_fisica_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.radiestesia_graficos.imagem_fisica_url IS 'Imagem do produto físico (diferente da imagem digital)';


--
-- Name: COLUMN radiestesia_graficos.disponivel_loja; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.radiestesia_graficos.disponivel_loja IS 'Se tem versão física disponível na loja';


