--
-- Name: sala_ferramentas; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sala_ferramentas (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    sala_id uuid NOT NULL,
    ferramenta_chave text NOT NULL,
    ferramenta_nome text NOT NULL,
    ferramenta_descricao text DEFAULT ''::text,
    icone text DEFAULT 'wrench'::text,
    rota text NOT NULL,
    ordem integer DEFAULT 0 NOT NULL,
    ativa boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    tipo text DEFAULT 'custom'::text,
    portal_minimo public.portal_type DEFAULT 'pre_iniciada'::public.portal_type,
    has_blocks boolean DEFAULT false,
    slug text,
    portal_id uuid,
    tipo_ferramenta text,
    origem_metodologica text,
    vinculo_metodologico text,
    finalidade_pratica text,
    familia_id uuid,
    texto_quando_usar text,
    texto_o_que_sustenta text,
    texto_como_atravessar text,
    categoria_badge text DEFAULT 'padrao'::text,
    familia_simbolica text,
    modo_uso text[] DEFAULT '{}'::text[],
    tipo_fechamento text,
    bloco_interativo_requerido boolean DEFAULT true,
    status_criacao text DEFAULT 'rascunho'::text,
    categoria_metodo text,
    proximo_passo text,
    ferramenta_pai_id uuid,
    e_complementar boolean DEFAULT false,
    CONSTRAINT sala_ferramentas_categoria_badge_check CHECK ((categoria_badge = ANY (ARRAY['padrao'::text, 'autoral'::text, 'metodo_oracula'::text])))
);


--
-- Name: COLUMN sala_ferramentas.portal_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sala_ferramentas.portal_id IS 'Optional: Link ferramenta directly to a Portal (conteudo_travessias). Ferramentas in Sala da Formação should always have a portal_id.';


--
-- Name: COLUMN sala_ferramentas.tipo_ferramenta; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sala_ferramentas.tipo_ferramenta IS 'Values: diagnostico, leitura_simbolica, autoleitura, conducao_terapeutica, ritual_simbolico, ferramenta_narrativa';


--
-- Name: COLUMN sala_ferramentas.origem_metodologica; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sala_ferramentas.origem_metodologica IS 'Values: padrao_psicologico, metodo_oracula, metodo_hibrido';


--
-- Name: COLUMN sala_ferramentas.vinculo_metodologico; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sala_ferramentas.vinculo_metodologico IS 'Values: pertence_metodo_oracula, ferramenta_apoio, ferramenta_externa_integrada';


--
-- Name: COLUMN sala_ferramentas.texto_quando_usar; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sala_ferramentas.texto_quando_usar IS 'Texto explicando o contexto de uso da ferramenta';


--
-- Name: COLUMN sala_ferramentas.texto_o_que_sustenta; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sala_ferramentas.texto_o_que_sustenta IS 'Texto ético sobre o que a ferramenta sustenta (sem promessas de cura)';


--
-- Name: COLUMN sala_ferramentas.texto_como_atravessar; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sala_ferramentas.texto_como_atravessar IS 'Orientação de uso: individual, sessão, grupo';


--
-- Name: COLUMN sala_ferramentas.categoria_badge; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sala_ferramentas.categoria_badge IS 'Badge visual: padrao, autoral, metodo_oracula';


--
-- Name: COLUMN sala_ferramentas.familia_simbolica; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sala_ferramentas.familia_simbolica IS 'Família simbólica: ego_identidade, sombra, corpo, imprevisivel, narrativa, oraculares';


--
-- Name: COLUMN sala_ferramentas.modo_uso; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sala_ferramentas.modo_uso IS 'Valores válidos: pessoal, sessao, grupo, entre_sessoes';


--
-- Name: COLUMN sala_ferramentas.tipo_fechamento; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sala_ferramentas.tipo_fechamento IS 'Valores válidos: registro, integracao, pausa_simbolica';


--
-- Name: COLUMN sala_ferramentas.status_criacao; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sala_ferramentas.status_criacao IS 'Valores válidos: rascunho, pronto, publicado';


--
-- Name: COLUMN sala_ferramentas.categoria_metodo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sala_ferramentas.categoria_metodo IS 'diagnostico, conducao, cartografia, integracao, autoexploracao, comunidade, formacao';


--
-- Name: COLUMN sala_ferramentas.proximo_passo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sala_ferramentas.proximo_passo IS 'Rota ou ID da ferramenta seguinte no fluxo do método';


--
-- Name: COLUMN sala_ferramentas.ferramenta_pai_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sala_ferramentas.ferramenta_pai_id IS 'Se complementar, aponta para a ferramenta principal';


--
-- Name: COLUMN sala_ferramentas.e_complementar; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sala_ferramentas.e_complementar IS 'Se true, é sub-ferramenta de outra';


