-- Name: upsell_opportunities; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.upsell_opportunities (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid,
    rule_id uuid,
    segment_from text NOT NULL,
    segment_to text NOT NULL,
    reason text,
    engagement_score double precision,
    churn_risk double precision,
    status public.upsell_status DEFAULT 'pending'::public.upsell_status,
    last_action_at timestamp with time zone,
    converted_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    channel_used text,
    refusal_count integer DEFAULT 0,
    last_offered_at timestamp with time zone,
    paused_until timestamp with time zone,
    ignored_count integer DEFAULT 0,
    declined_count integer DEFAULT 0,
    historical_segment_rate double precision,
    timing_factor double precision,
    probability_score double precision,
    probability_reason text,
    first_touch_channel text,
    last_touch_channel text,
    touch_count integer DEFAULT 0,
    days_to_conversion integer,
    estimated_value numeric(10,2)
);


--
-- Name: upsell_revenue_intelligence; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.upsell_revenue_intelligence AS
 SELECT segment_from,
    segment_to,
    COALESCE(channel_used, 'Pendente'::text) AS channel_used,
    count(*) AS total_sent,
    count(*) FILTER (WHERE (status = 'converted'::public.upsell_status)) AS conversions,
    round(((((count(*) FILTER (WHERE (status = 'converted'::public.upsell_status)))::double precision / (NULLIF(count(*), 0))::double precision) * (100)::double precision))::numeric, 1) AS acceptance_rate,
    sum(COALESCE(estimated_value, (0)::numeric)) FILTER (WHERE (status = 'converted'::public.upsell_status)) AS revenue_generated,
    avg(days_to_conversion) AS avg_days_to_convert,
    count(*) FILTER (WHERE ((declined_count > 0) OR (status = 'ignored'::public.upsell_status))) AS fatigue_count
   FROM public.upsell_opportunities
  GROUP BY segment_from, segment_to, channel_used;


--
-- Name: upsell_rules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.upsell_rules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    segment_from text NOT NULL,
    segment_to text NOT NULL,
    min_engagement_score double precision DEFAULT 0.7,
    max_churn_risk double precision DEFAULT 0.3,
    min_recurrent_use_days integer DEFAULT 15,
    estimated_value_increase numeric(10,2),
    is_active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);


--
-- Name: upsell_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.upsell_stats AS
 SELECT segment_from,
    segment_to,
    count(*) AS total_opportunities,
    count(*) FILTER (WHERE (status = 'converted'::public.upsell_status)) AS conversions,
        CASE
            WHEN (count(*) > 0) THEN (((count(*) FILTER (WHERE (status = 'converted'::public.upsell_status)))::double precision / (count(*))::double precision) * (100)::double precision)
            ELSE (0)::double precision
        END AS conversion_rate,
    ((sum(
        CASE
            WHEN (status = 'converted'::public.upsell_status) THEN 1
            ELSE 0
        END))::numeric * ( SELECT r.estimated_value_increase
           FROM public.upsell_rules r
          WHERE ((r.segment_from = o.segment_from) AND (r.segment_to = o.segment_to))
         LIMIT 1)) AS total_revenue
   FROM public.upsell_opportunities o
  GROUP BY segment_from, segment_to;


