--
-- Name: v_canteiro_admin_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_canteiro_admin_stats WITH (security_invoker='true') AS
 SELECT ( SELECT count(*) AS count
           FROM public.jardim_psique_registros) AS total_registros_jardim,
    ( SELECT count(DISTINCT jardim_psique_registros.user_id) AS count
           FROM public.jardim_psique_registros
          WHERE (jardim_psique_registros.arquivado = false)) AS usuarias_ativas_jardim,
    ( SELECT count(*) AS count
           FROM public.collective_bed_entries) AS total_publicacoes_canteiro,
    ( SELECT count(*) AS count
           FROM public.collective_bed_entries
          WHERE ((collective_bed_entries.aprovado_por_admin = true) AND (collective_bed_entries.publicado_em IS NOT NULL))) AS publicacoes_aprovadas,
    ( SELECT count(*) AS count
           FROM public.collective_bed_entries
          WHERE (collective_bed_entries.rejeitado = true)) AS publicacoes_rejeitadas,
    ( SELECT count(DISTINCT collective_bed_entries.user_id) AS count
           FROM public.collective_bed_entries) AS usuarias_que_publicaram,
    ( SELECT count(*) AS count
           FROM public.collective_bed_entries
          WHERE (collective_bed_entries.created_at > (now() - '30 days'::interval))) AS publicacoes_ultimos_30_dias,
    ( SELECT count(*) AS count
           FROM public.jardim_psique_registros
          WHERE (jardim_psique_registros.created_at > (now() - '30 days'::interval))) AS registros_jardim_ultimos_30_dias;


