CREATE VIEW public.v_canteiro_per_student_stats WITH (security_invoker='true') AS
 SELECT cbe.user_id,
    p.nome,
    p.email,
    count(*) AS total_publicacoes,
    count(*) FILTER (WHERE ((cbe.aprovado_por_admin = false) AND (cbe.rejeitado = false))) AS em_curadoria,
    count(*) FILTER (WHERE (cbe.aprovado_por_admin = true)) AS publicadas,
    count(*) FILTER (WHERE (cbe.rejeitado = true)) AS recusadas,
    max(cbe.created_at) AS ultimo_compartilhamento
   FROM (public.collective_bed_entries cbe
     JOIN public.profiles p ON ((p.id = cbe.user_id)))
  GROUP BY cbe.user_id, p.nome, p.email;


--
-- Name: v_formation_progress; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_formation_progress WITH (security_invoker='true') AS
 WITH user_aula_completed AS (
         SELECT uap.user_id,
            uap.aula_id,
            ca.titulo AS aula_titulo,
            ca.ordem AS aula_ordem,
            ca.travessia_id,
            ct.titulo AS travessia_titulo,
            ct.ordem AS travessia_ordem,
            ct.sala_id,
            uap.completed_at
           FROM ((public.user_aula_progress uap
             LEFT JOIN public.conteudo_aulas ca ON ((ca.id = uap.aula_id)))
             LEFT JOIN public.conteudo_travessias ct ON ((ct.id = ca.travessia_id)))
        ), user_travessia_status AS (
         SELECT uac.user_id,
            uac.travessia_id,
            uac.travessia_titulo,
            uac.travessia_ordem,
            uac.sala_id,
            count(uac.aula_id) AS aulas_completed,
            ( SELECT count(*) AS count
                   FROM public.conteudo_aulas
                  WHERE ((conteudo_aulas.travessia_id = uac.travessia_id) AND (conteudo_aulas.publicado = true))) AS total_aulas,
            max(uac.completed_at) AS last_activity
           FROM user_aula_completed uac
          WHERE (uac.travessia_id IS NOT NULL)
          GROUP BY uac.user_id, uac.travessia_id, uac.travessia_titulo, uac.travessia_ordem, uac.sala_id
        ), user_ritual_status AS (
         SELECT rp.user_id,
            rp.ritual_id,
            rd.nome AS ritual_nome,
            rd.tipo,
            rd.trigger_event,
            rd.trigger_context_type,
            rd.trigger_context_id,
            rp.status AS ritual_status,
            rp.completed_at AS ritual_completed_at
           FROM (public.ritual_passages rp
             LEFT JOIN public.ritual_definitions rd ON ((rd.id = rp.ritual_id)))
        )
 SELECT id AS user_id,
    portal AS current_portal,
    nome AS nome_exibicao,
    role,
    created_at AS joined_at,
    ( SELECT COALESCE(json_agg(json_build_object('id', uts.travessia_id, 'titulo', uts.travessia_titulo, 'ordem', uts.travessia_ordem, 'sala_id', uts.sala_id, 'completed_at', uts.last_activity)), '[]'::json) AS "coalesce"
           FROM user_travessia_status uts
          WHERE ((uts.user_id = p.id) AND (uts.aulas_completed = uts.total_aulas) AND (uts.total_aulas > 0))) AS completed_travessias,
    ( SELECT COALESCE(json_agg(json_build_object('id', uts.travessia_id, 'titulo', uts.travessia_titulo, 'ordem', uts.travessia_ordem, 'sala_id', uts.sala_id, 'aulas_done', uts.aulas_completed, 'aulas_total', uts.total_aulas)), '[]'::json) AS "coalesce"
           FROM user_travessia_status uts
          WHERE ((uts.user_id = p.id) AND (uts.aulas_completed < uts.total_aulas) AND (uts.aulas_completed > 0))) AS active_travessias,
    ( SELECT COALESCE(json_agg(json_build_object('id', urs.ritual_id, 'nome', urs.ritual_nome, 'tipo', urs.tipo, 'context', urs.trigger_context_id, 'completed_at', urs.ritual_completed_at)), '[]'::json) AS "coalesce"
           FROM user_ritual_status urs
          WHERE ((urs.user_id = p.id) AND (urs.ritual_status = 'completed'::public.ritual_status))) AS completed_rituals
   FROM public.profiles p
  WHERE (id IS NOT NULL);


