--
-- Name: vw_oraculo_portais_resumo; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_oraculo_portais_resumo AS
 SELECT id,
    slug,
    nome,
    ordem,
    status,
    descricao_curta,
    tempo_estimado,
    updated_at,
    (EXISTS ( SELECT 1
           FROM public.oraculo_portal_essencia e
          WHERE (e.portal_id = p.id))) AS tem_essencia,
    (EXISTS ( SELECT 1
           FROM public.oraculo_portal_audios a
          WHERE ((a.portal_id = p.id) AND (a.tipo = 'principal'::text)))) AS tem_audio_principal,
    (EXISTS ( SELECT 1
           FROM public.oraculo_portal_laboratorios l
          WHERE (l.portal_id = p.id))) AS tem_laboratorio,
    (EXISTS ( SELECT 1
           FROM public.oraculo_portal_jardins j
          WHERE (j.portal_id = p.id))) AS tem_jardins,
    (EXISTS ( SELECT 1
           FROM public.oraculo_portal_aplicacoes ap
          WHERE (ap.portal_id = p.id))) AS tem_aplicacao,
    (EXISTS ( SELECT 1
           FROM public.oraculo_portal_narroterapia n
          WHERE (n.portal_id = p.id))) AS tem_narroterapia,
    (EXISTS ( SELECT 1
           FROM public.oraculo_portal_forjas f
          WHERE (f.portal_id = p.id))) AS tem_forja,
    (EXISTS ( SELECT 1
           FROM public.oraculo_portal_ferramentas ft
          WHERE (ft.portal_id = p.id))) AS tem_ferramenta,
    (EXISTS ( SELECT 1
           FROM public.oraculo_portal_riscos_eticos r
          WHERE (r.portal_id = p.id))) AS tem_risco_etico
   FROM public.oraculo_portais p;


